public class Product {
    // Field (backing store, private)
    private decimal _price;
    private static int _instanceCount = 0;  // static: shared across all instances

    // Auto-property (compiler generates backing field)
    public string Name { get; set; }
    public int Id { get; init; }  // init: set only in constructor/object initialiser

    // Property with validation in setter
    public decimal Price {
        get => _price;
        set {
            if (value < 0) throw new ArgumentOutOfRangeException(nameof(value));
            _price = value;
        }
    }

    // Computed property (no backing field)
    public string DisplayName => $"{Name} (${Price:F2})";

    // Constructor (primary constructor C# 12 shown later)
    public Product(int id, string name, decimal price) {
        Id = id;
        Name = name ?? throw new ArgumentNullException(nameof(name));
        Price = price;  // calls setter with validation
        _instanceCount++;
    }

    // Method
    public void ApplyDiscount(decimal percentage) {
        if (percentage < 0 || percentage > 100)
            throw new ArgumentOutOfRangeException(nameof(percentage));
        Price *= (1 - percentage / 100);
    }

    // Static method
    public static int GetInstanceCount() => _instanceCount;

    // Override ToString for debugging
    public override string ToString() => $"Product({Id}: {Name})"; 
}

// Usage
var p = new Product(1, "Widget", 9.99m);
p.ApplyDiscount(10);  // price becomes 8.991

// Object initialiser (sets properties after constructor)
var p2 = new Product(2, "Gadget", 19.99m) {
    Name = "Super Gadget"  // sets Name after constructor runs
};
