// Base class
public abstract class Shape {
    public string Color { get; set; } = "Black";

    // virtual: can be overridden
    public virtual string Describe() => $"A {Color} shape";

    // abstract: MUST be overridden (class must be abstract)
    public abstract double Area();

    public void PrintInfo() =>  // non-virtual: shared across all derived
        Console.WriteLine($"{Describe()}, area={Area():F2}");
}

// Derived class
public class Circle : Shape {  // single base class
    public double Radius { get; }

    public Circle(double radius, string color) {
        Radius = radius;
        Color = color;  // inherited property
    }

    // override abstract method (required)
    public override double Area() => Math.PI * Radius * Radius;

    // override virtual method (optional)
    public override string Describe() =>
        base.Describe() + $" (circle, r={Radius})";  // calls base impl
}

public sealed class SpecialCircle : Circle {  // can extend Circle
    public SpecialCircle(double r) : base(r, "Gold") {}  // base ctor
    // sealed class: no further subclassing
}

// Polymorphism
List<Shape> shapes = new() {
    new Circle(5, "Red"),
    new Rectangle(3, 4, "Blue"),
};
foreach (var s in shapes)
    s.PrintInfo();  // calls overridden Area() and Describe() for each

// Type check
if (shape is Circle c)
    Console.WriteLine($"Circle radius: {c.Radius}");  // c is Circle
