// Struct: value type — stack allocated when local
struct Coordinate { public double Lat, Lon; }  // 16 bytes, on stack
Coordinate coord = new() { Lat = 37.7, Lon = -122.4 };  // no heap alloc

// Class: reference type — heap allocated
class Customer { public string Name; public decimal Balance; }
Customer c = new Customer();  // heap allocation, GC tracks it

// Span<T>: stack-allocated view over memory (no heap alloc)
byte[] buffer = new byte[100];         // heap
Span<byte> span = buffer.AsSpan(0, 50);  // stack-only view, no copy
Span<byte> stackSpan = stackalloc byte[64];  // 64 bytes on stack!

// ref struct: cannot escape to heap (always stack)
ref struct StackOnlyParser {
    private ReadOnlySpan<char> _data;
    public StackOnlyParser(ReadOnlySpan<char> data) => _data = data;
    // Cannot be boxed, cannot be stored in class fields, cannot be awaited
}

// LOH — objects > 85,000 bytes
byte[] largeBuffer = new byte[86000];  // goes to LOH, not Gen 0
// LOH not compacted → fragmentation over time
// Use ArrayPool to avoid LOH allocations:
byte[] rented = ArrayPool<byte>.Shared.Rent(86000);  // reuses LOH arrays

// Unmanaged memory (PInvoke, COM interop)
IntPtr ptr = Marshal.AllocHGlobal(1024);  // unmanaged allocation
try {
    // ... use ptr
} finally {
    Marshal.FreeHGlobal(ptr);  // must free manually
}
