// Entity classes (map to database tables)
public class Product {
    public int Id { get; set; }           // PK (by convention: Id or ProductId)
    public string Name { get; set; } = "";
    public decimal Price { get; set; }
    public bool IsActive { get; set; } = true;
    public int CategoryId { get; set; }   // FK (by convention: CategoryId)
    public Category Category { get; set; } = null!;  // navigation property
    public ICollection<OrderItem> OrderItems { get; set; } = new List<OrderItem>();
}

public class Category {
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public ICollection<Product> Products { get; set; } = new List<Product>();
}

// DbContext: the unit of work / session
public class AppDbContext : DbContext {
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Order> Orders => Set<Order>();

    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) {}
}

// CRUD operations
public class ProductService {
    private readonly AppDbContext _db;
    public ProductService(AppDbContext db) => _db = db;

    // Read
    public async Task<List<Product>> GetActiveAsync() =>
        await _db.Products
            .Where(p => p.IsActive)
            .Include(p => p.Category)   // eager-load related entity
            .OrderBy(p => p.Name)
            .ToListAsync();

    // Create
    public async Task<Product> CreateAsync(Product product) {
        _db.Products.Add(product);   // adds to change tracker (state: Added)
        await _db.SaveChangesAsync(); // generates INSERT SQL
        return product;  // product.Id now set by database
    }

    // Update
    public async Task UpdatePriceAsync(int id, decimal newPrice) {
        var product = await _db.Products.FindAsync(id);
        if (product is null) throw new NotFoundException();
        product.Price = newPrice;     // EF tracks this change (state: Modified)
        await _db.SaveChangesAsync(); // generates UPDATE SQL
    }

    // Delete
    public async Task DeleteAsync(int id) {
        var product = await _db.Products.FindAsync(id);
        if (product is null) return;
        _db.Products.Remove(product); // state: Deleted
        await _db.SaveChangesAsync(); // generates DELETE SQL
    }
}
```

**EF Core translates LINQ → SQL**:
`_db.Products.Where(p => p.IsActive).Include(p => p.Category).OrderBy(p => p.Name)`
→ `SELECT p.*, c.* FROM Products p LEFT JOIN Categories c ON p.CategoryId=c.Id WHERE p.IsActive=1 ORDER BY p.Name`

