// Querying
public class ProductService(AppDbContext db) {

    // Simple query
    public Task<Product?> GetByIdAsync(int id) =>
        db.Products.FindAsync(id).AsTask(); // checks cache first, then DB

    // LINQ with multiple options
    public Task<List<Product>> SearchAsync(string? name, decimal? maxPrice) =>
        db.Products
            .AsNoTracking()                  // read-only: skip change tracking
            .Where(p => name == null || p.Name.Contains(name))
            .Where(p => maxPrice == null || p.Price <= maxPrice)
            .OrderBy(p => p.Price)
            .Select(p => new Product { Id = p.Id, Name = p.Name, Price = p.Price })
            .ToListAsync();

    // Raw SQL (when LINQ can't express the query)
    public Task<List<Product>> GetTopSellingAsync() =>
        db.Products
            .FromSqlRaw("SELECT p.* FROM Products p " +
                        "JOIN OrderItems oi ON p.Id = oi.ProductId " +
                        "GROUP BY p.Id, p.Name, p.Price " +
                        "ORDER BY SUM(oi.Quantity) DESC " +
                        "LIMIT 10")
            .ToListAsync();

    // Execute non-query SQL
    public Task ArchiveOldOrdersAsync() =>
        db.Database.ExecuteSqlRawAsync(
            "UPDATE Orders SET IsArchived=1 WHERE CreatedAt < {0}",
            DateTime.UtcNow.AddYears(-1));  // parameterised

    // Transaction control
    public async Task TransferAsync(int fromId, int toId, decimal amount) {
        using var tx = await db.Database.BeginTransactionAsync();
        try {
            var from = await db.Wallets.FindAsync(fromId);
            var to = await db.Wallets.FindAsync(toId);
            from!.Balance -= amount;
            to!.Balance += amount;
            await db.SaveChangesAsync();  // both changes in one transaction
            await tx.CommitAsync();
        } catch {
            await tx.RollbackAsync();
            throw;
        }
    }
}
