// ── Data Annotations approach ──
public class Product {
    [Key]                          // PK (redundant if named Id)
    [DatabaseGenerated(DatabaseGeneratedOption.Identity)]
    public int Id { get; set; }

    [Required]
    [MaxLength(100)]
    [Column("ProductName")]        // maps to different column name
    public string Name { get; set; } = "";

    [Precision(18, 2)]             // decimal(18,2) in SQL
    public decimal Price { get; set; }

    [ForeignKey(nameof(Category))] // explicit FK name
    public int CategoryId { get; set; }
    public Category Category { get; set; } = null!;

    [Timestamp]                    // rowversion for optimistic concurrency
    public byte[] RowVersion { get; set; } = null!;
}

[Index(nameof(Name), IsUnique = true)]  // class-level unique index
public class Category { ... }

// ── Fluent API approach (OnModelCreating) ──
protected override void OnModelCreating(ModelBuilder model) {
    model.Entity<Product>(entity => {
        entity.HasKey(p => p.Id);
        entity.Property(p => p.Name)
              .IsRequired()
              .HasMaxLength(100)
              .HasColumnName("ProductName");
        entity.Property(p => p.Price)
              .HasColumnType("decimal(18,2)");
        entity.HasIndex(p => p.Name).IsUnique();
        entity.HasOne(p => p.Category)
              .WithMany(c => c.Products)
              .HasForeignKey(p => p.CategoryId)
              .OnDelete(DeleteBehavior.Restrict);  // no cascade delete

        // Table splitting: one C# class → multiple tables
        entity.ToTable("Products");

        // Value conversion: enum stored as string
        entity.Property(p => p.Status)
              .HasConversion<string>();
    });

    // Separate configuration class (preferred for large models)
    model.ApplyConfiguration(new OrderConfiguration());
}

// IEntityTypeConfiguration<T> — best practice for large projects
public class OrderConfiguration : IEntityTypeConfiguration<Order> {
    public void Configure(EntityTypeBuilder<Order> b) {
        b.HasKey(o => o.Id);
        b.Property(o => o.TotalAmount).HasColumnType("decimal(18,2)");
        b.HasMany(o => o.Items).WithOne(i => i.Order)
            .HasForeignKey(i => i.OrderId).OnDelete(DeleteBehavior.Cascade);
        b.HasIndex(o => new { o.CustomerId, o.CreatedAt });
    }
}
