// Simple periodic background service
public class CleanupService : BackgroundService {
    private readonly ILogger<CleanupService> _logger;
    private readonly IServiceScopeFactory _scopeFactory;  // needed for scoped services in singleton

    public CleanupService(ILogger<CleanupService> logger, IServiceScopeFactory scopeFactory) {
        _logger = logger;
        _scopeFactory = scopeFactory;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            _logger.LogInformation("Running cleanup at {Time}", DateTimeOffset.Now);

            // Use scope to access scoped services (DbContext)
            using var scope = _scopeFactory.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

            var cutoff = DateTime.UtcNow.AddDays(-30);
            await db.Sessions
                .Where(s => s.ExpiresAt < cutoff)
                .ExecuteDeleteAsync(stoppingToken);

            await Task.Delay(TimeSpan.FromHours(1), stoppingToken);  // wait 1 hour
        }
    }
}

// Message consumer background service
public class OrderProcessorService : BackgroundService {
    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        await foreach (var message in _queue.ReadAllAsync(stoppingToken)) {
            try {
                await ProcessOrderAsync(message);
            } catch (Exception ex) {
                _logger.LogError(ex, "Failed to process order {Id}", message.OrderId);
                // don't rethrow — service keeps running
            }
        }
    }
}

// Registration
builder.Services.AddHostedService<CleanupService>();
builder.Services.AddHostedService<OrderProcessorService>();
