static bool TryParseRecord(ReadOnlySpan<char> line, out Record record) {
    var comma = line.IndexOf(',');
    if (comma < 0) { record = default; return false; }

    var idSpan = line[..comma];
    var nameSpan = line[(comma + 1)..];

    if (!int.TryParse(idSpan, out int id)) { record = default; return false; }
    record = new Record(id, new string(nameSpan));  // only one allocation (the string)
    return true;
