// ── IQueryable vs IEnumerable — critical distinction ──

// BAD: loads ALL products into memory, then filters in C#
var expensive = _db.Products.ToList()  // SQL: SELECT * FROM Products (all rows)
    .Where(p => p.Price > 100);         // C# in-memory filter

// GOOD: EF Core translates Where to SQL
var expensive = _db.Products           // IQueryable<Product>
    .Where(p => p.Price > 100)          // SQL: WHERE Price > 100
    .ToListAsync();                     // materializes only matching rows

// ── Deferred vs Immediate execution ──
IQueryable<Product> query = _db.Products.Where(p => p.IsActive);  // not executed yet
query = query.Where(p => p.Price < 50);   // still not executed — adds to query
var result = await query.ToListAsync();    // NOW executes one SQL query

// ── Avoiding multiple enumeration ──
IEnumerable<int> numbers = Enumerable.Range(1, 1_000_000);
// BAD: iterates the source twice
bool hasAny = numbers.Any();
int count = numbers.Count();
// GOOD: materialize once
var list = numbers.ToList();
bool hasAny = list.Count > 0;
int count = list.Count;

// ── Projection to reduce data transferred ──
// BAD: loads entire Product entity, then extracts two fields
var names = _db.Products.ToList().Select(p => p.Name);
// GOOD: SQL SELECT Name, Price only
var names = await _db.Products
    .Where(p => p.IsActive)
    .Select(p => new { p.Name, p.Price })  // SQL: SELECT Name, Price
