// Polly v8 with Microsoft.Extensions.Resilience (recommended for .NET 8+)
builder.Services.AddHttpClient<IPaymentService, PaymentService>()
    .AddResilienceHandler("payment-pipeline", pipeline => {
        // Retry: 3 times with exponential backoff + jitter
        pipeline.AddRetry(new HttpRetryStrategyOptions {
            MaxRetryAttempts = 3,
            Delay = TimeSpan.FromMilliseconds(200),
            BackoffType = DelayBackoffType.Exponential,
            UseJitter = true,  // ±25% jitter to prevent thundering herd
            ShouldHandle = args => args.Outcome switch {
                { Exception: HttpRequestException } => PredicateResult.True(),
                { Result.StatusCode: HttpStatusCode.TooManyRequests } => PredicateResult.True(),
                { Result.StatusCode: >= HttpStatusCode.InternalServerError } => PredicateResult.True(),
                _ => PredicateResult.False()
            }
        });

        // Circuit Breaker: open after 50% failures in a 30-second window
        pipeline.AddCircuitBreaker(new HttpCircuitBreakerStrategyOptions {
            FailureRatio = 0.5,
            SamplingDuration = TimeSpan.FromSeconds(30),
            MinimumThroughput = 10,      // at least 10 requests before tripping
            BreakDuration = TimeSpan.FromSeconds(15)  // open for 15s, then half-open
        });

        // Timeout: cancel if payment call takes > 5 seconds
        pipeline.AddTimeout(TimeSpan.FromSeconds(5));
    });

