    public async Task<PaymentResult> ChargeAsync(decimal amount) {
        // Retry, circuit breaker, and timeout applied automatically
        var response = await http.PostAsJsonAsync("/charge", new { amount });
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PaymentResult>() ?? throw new();
    }
    // No Polly code in business logic — policy applied at registration
}

