public class Order : AggregateRoot<Guid> {
    private readonly List<OrderItem> _items = new();
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();
    public OrderStatus Status { get; private set; } = OrderStatus.Pending;
    public Money Total { get; private set; } = Money.Zero;
    public CustomerId CustomerId { get; private set; }

    private Order() {}  // EF Core needs parameterless ctor

    public static Order Create(CustomerId customerId) {
        var order = new Order { CustomerId = customerId };
        order.AddDomainEvent(new OrderCreatedEvent(order.Id, customerId));
        return order;
    }

    public void AddItem(ProductId productId, int quantity, Money unitPrice) {
        if (Status != OrderStatus.Pending)
            throw new DomainException("Cannot modify a non-pending order");
        if (quantity <= 0)
            throw new DomainException("Quantity must be positive");

        var existing = _items.FirstOrDefault(i => i.ProductId == productId);
        if (existing is not null)
            existing.IncreaseQuantity(quantity);
        else
            _items.Add(new OrderItem(productId, quantity, unitPrice));

        Total = Money.Sum(_items.Select(i => i.Subtotal));
    }

    public void Place() {
        if (!_items.Any()) throw new DomainException("Cannot place an empty order");
        Status = OrderStatus.Placed;
        AddDomainEvent(new OrderPlacedEvent(Id, CustomerId, Total));
    }
}

// Value Object — immutable, equality by value
public record Money(decimal Amount, string Currency) {
    public static readonly Money Zero = new(0, "USD");
    public Money Add(Money other) {
        if (Currency != other.Currency) throw new DomainException("Currency mismatch");
        return new Money(Amount + other.Amount, Currency);
    }
    public static Money Sum(IEnumerable<Money> monies) =>
        monies.Aggregate(Zero, (acc, m) => acc.Add(m));
}

