public class OutboxMessage {
    public Guid Id { get; init; } = Guid.NewGuid();
    public string Type { get; init; } = "";
    public string Payload { get; init; } = "";
    public DateTime CreatedAt { get; init; } = DateTime.UtcNow;
    public DateTime? ProcessedAt { get; set; }  // null = not yet published
    public string? Error { get; set; }
}

// Write to outbox in the same transaction as business data
public class OrderService(AppDbContext db) {
    public async Task PlaceOrderAsync(PlaceOrderCommand cmd) {
        var order = Order.Create(cmd.CustomerId);
        order.Place();

        db.Orders.Add(order);

        // Save event to outbox — same transaction
        db.OutboxMessages.Add(new OutboxMessage {
            Type = nameof(OrderPlacedEvent),
            Payload = JsonSerializer.Serialize(new OrderPlacedEvent(order.Id, cmd.CustomerId))
        });

        await db.SaveChangesAsync();  // both Order + OutboxMessage saved atomically
    }
}

// Outbox processor (Background Service)
public class OutboxProcessor(IServiceScopeFactory scopeFactory, IPublishEndpoint bus)
    : BackgroundService {

    protected override async Task ExecuteAsync(CancellationToken ct) {
        while (!ct.IsCancellationRequested) {
            using var scope = scopeFactory.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

            var pending = await db.OutboxMessages
                .Where(m => m.ProcessedAt == null)
                .OrderBy(m => m.CreatedAt)
                .Take(100)
                .ToListAsync(ct);

            foreach (var msg in pending) {
                try {
                    var eventType = Type.GetType(msg.Type)!;
                    var @event = JsonSerializer.Deserialize(msg.Payload, eventType)!;
                    await bus.Publish(@event, ct);
                    msg.ProcessedAt = DateTime.UtcNow;
                } catch (Exception ex) {
                    msg.Error = ex.Message;
                }
            }
            await db.SaveChangesAsync(ct);
            await Task.Delay(TimeSpan.FromSeconds(5), ct);
        }
    }
}

