// MassTransit Saga State Machine — Order Processing Saga
public class OrderStateMachine : MassTransitStateMachine<OrderState> {
    public State Submitted { get; private set; } = null!;
    public State PaymentProcessing { get; private set; } = null!;
    public State Fulfilling { get; private set; } = null!;
    public State Completed { get; private set; } = null!;
    public State Failed { get; private set; } = null!;

    public Event<OrderPlacedEvent> OrderPlaced { get; private set; } = null!;
    public Event<PaymentCompletedEvent> PaymentCompleted { get; private set; } = null!;
    public Event<PaymentFailedEvent> PaymentFailed { get; private set; } = null!;
    public Event<FulfillmentCompletedEvent> FulfillmentCompleted { get; private set; } = null!;

    public OrderStateMachine() {
        InstanceState(x => x.CurrentState);

        Event(() => OrderPlaced, x => x.CorrelateById(ctx => ctx.Message.OrderId));
        Event(() => PaymentCompleted, x => x.CorrelateById(ctx => ctx.Message.OrderId));
        Event(() => PaymentFailed, x => x.CorrelateById(ctx => ctx.Message.OrderId));

        Initially(
            When(OrderPlaced)
                .Then(ctx => ctx.Saga.OrderId = ctx.Message.OrderId)
                .PublishAsync(ctx => ctx.Init<ProcessPaymentCommand>(new { ctx.Saga.OrderId }))
                .TransitionTo(PaymentProcessing)
        );

        During(PaymentProcessing,
            When(PaymentCompleted)
                .PublishAsync(ctx => ctx.Init<FulfillOrderCommand>(new { ctx.Saga.OrderId }))
                .TransitionTo(Fulfilling),
            When(PaymentFailed)
                // Compensating transaction: cancel the order
                .PublishAsync(ctx => ctx.Init<CancelOrderCommand>(new { ctx.Saga.OrderId, Reason = "Payment failed" }))
                .TransitionTo(Failed)
        );

        During(Fulfilling,
            When(FulfillmentCompleted)
                .TransitionTo(Completed)
                .Finalize()
        );
    }
}

// Saga state persisted in DB (survives restarts)
public class OrderState : SagaStateMachineInstance {
    public Guid CorrelationId { get; set; }  // = OrderId
    public string CurrentState { get; set; } = "";
    public Guid OrderId { get; set; }
}
