// Old pattern (still works, but Lock is preferred in C# 13+)
private readonly object _syncRoot = new();
public void OldMethod() {
    lock (_syncRoot) {
        // critical section
        _counter++;
    }
}

// C# 13 — System.Threading.Lock
public class ThreadSafeCounter {
    private readonly Lock _lock = new();
    private int _count = 0;

    public void Increment() {
        lock (_lock) {          // C# 13: lock() works directly on Lock type
            _count++;
        }
    }

    // Alternative: explicit scope (Dispose releases the lock)
    public int GetAndReset() {
        using (_lock.EnterScope()) {
            var value = _count;
            _count = 0;
            return value;
        }
    }

    // Try-enter pattern
    public bool TryIncrement() {
        if (_lock.TryEnter()) {
            try {
                _count++;
                return true;
            } finally {
                _lock.Exit();
            }
        }
        return false;
    }
}

// Key difference from lock(object): Lock.EnterScope() returns a ref struct
// that's disposed automatically — no try/finally boilerplate
