using System.Runtime.CompilerServices;

public class Logger {
    // Old overload (kept for binary compatibility)
    public void Log(params string[] messages) {
        foreach (var m in messages) WriteToSink(m);
    }

    // New, preferred zero-allocation overload
    [OverloadResolutionPriority(1)]  // higher priority wins
    public void Log(params ReadOnlySpan<string> messages) {
        foreach (var m in messages) WriteToSink(m);  // no heap allocation
    }
}

// Callers automatically use the Span overload (priority 1 > 0)
var logger = new Logger();
logger.Log("hello", "world");  // calls Log(params ReadOnlySpan<string>)

// Force the old overload explicitly (override priority)
string[] msgs = ["hello", "world"];
logger.Log((string[])msgs);   // explicit cast forces array overload

// Negative priority — deprioritize (useful for marking obsolete overloads
// that can't be removed yet)
public class Api {
    [OverloadResolutionPriority(-1)]  // prefer the other overload
    [Obsolete("Use the IEnumerable overload instead")]
    public void Process(params object[] items) { ... }

    public void Process(params IEnumerable<object> items) { ... }  // preferred (priority 0)
}
