// User-defined compound assignment
public class NumberList {
    private readonly List<int> _items = new();

    // Binary + (creates new list)
    public static NumberList operator +(NumberList a, int value) {
        var result = new NumberList();
        result._items.AddRange(a._items);
        result._items.Add(value);
        return result;
    }

    // Compound += (mutates in-place — C# 14)
    public static NumberList operator +=(NumberList list, int value) {
        list._items.Add(value);  // in-place mutation — no new list created
        return list;
    }

    public int Count => _items.Count;
}

var list = new NumberList();
list += 1;   // calls operator +=, not operator +
list += 2;   // in-place, no allocations
list += 3;

// Without user-defined +=: list += 1 would expand to list = list + 1
//   calling operator+ which creates a new NumberList each time

// Mutable matrix example
public struct Matrix4x4Mutable {
    public static Matrix4x4Mutable operator +=(Matrix4x4Mutable a, Matrix4x4Mutable b) {
        // In-place matrix addition — modify 'a' directly
        for (int i = 0; i < 16; i++) a._data[i] += b._data[i];
        return a;
    }
}
