// EF Core 9: hierarchical partition key configuration
public class BloggingContext : DbContext {
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder model) {
        model.Entity<Post>(e => {
            // Hierarchical partition key: TenantId / AuthorId / Year
            e.HasPartitionKey(p => p.TenantId)  // level 1
             .HasPartitionKey(p => p.AuthorId)   // level 2 (sub-partition)
             .HasPartitionKey(p => p.Year);       // level 3

            // Or using the new multi-property syntax:
            e.HasPartitionKey(p => new { p.TenantId, p.AuthorId, p.Year });
        });
    }
}

public class Post {
