    .WithPartitionKey("tenant1", "author42", "2024")  // specify partition
    .FirstAsync(p => p.Id == "abc123");               // EF Core 9: uses point read API

// Cross-partition query (more expensive — use sparingly)
var recentPosts = await context.Posts
    .Where(p => p.TenantId == "tenant1" && p.Year == 2024)
    .OrderByDescending(p => p.Title)
    .Take(20)
