// Default EF Core behaviour: LINQ local variables → parameters
int limit = 10;
var products = await db.Products.Take(limit).ToListAsync();
// SQL: SELECT TOP (@limit) ... FROM Products  -- parameterised

// EF.Constant: force literal embedding
var top10 = await db.Products
    .Take(EF.Constant(10))  // SQL: SELECT TOP 10 ... FROM Products
    .ToListAsync();
// Useful when different values need different plans/indexes

var top100 = await db.Products
    .Take(EF.Constant(100))  // SQL: SELECT TOP 100 ... -- different cached plan
    .ToListAsync();

// EF.Parameter: force parameterisation even for normally-inlined values
// Normally 'true' would be inlined as a literal:
var active = await db.Products
    .Where(p => p.IsActive == EF.Parameter(true))  // forces: WHERE IsActive = @active
    .ToListAsync();

// Practical use: EF.Constant for known small limits, EF.Parameter for
// values that might change between calls but should share a plan
public async Task<List<Product>> GetTopProducts(int n) {
    return n <= 20
        ? await db.Products.Take(EF.Constant(n)).ToListAsync()  // inline for small n
        : await db.Products.Take(n).ToListAsync();              // parameterise for large n
}
