// Usage
public class ArticleSearchService(
    IVectorStore vectorStore,
    IEmbeddingGenerator<string, Embedding<float>> embedder) {

    private IVectorStoreRecordCollection<string, Article>? _collection;

    private async Task<IVectorStoreRecordCollection<string, Article>> GetCollectionAsync() {
        _collection ??= vectorStore.GetCollection<string, Article>("articles");
        await _collection.CreateCollectionIfNotExistsAsync();
        return _collection;
    }

    public async Task IndexArticleAsync(Article article) {
        article.Embedding = await embedder.GenerateEmbeddingVectorAsync(article.Content);
        var collection = await GetCollectionAsync();
        await collection.UpsertAsync(article);
    }

    public async Task<List<Article>> SearchAsync(string query, string? category = null) {
        var queryEmbedding = await embedder.GenerateEmbeddingVectorAsync(query);
        var collection = await GetCollectionAsync();

        var results = await collection.SearchAsync(queryEmbedding,
            new VectorSearchOptions<Article> {
                Top = 5,
                VectorProperty = a => a.Embedding,
                Filter = category is null ? null : r => r.Category == category
            });

        return await results.Results.Select(r => r.Record).ToListAsync();
    }
}
