// Grain interface
public interface ICounterGrain : IGrainWithStringKey {
    Task<int> IncrementAsync();
    Task<int> GetCountAsync();
    Task ResetAsync();
}

// Grain implementation with persistent state
public class CounterGrain : Grain, ICounterGrain {
    private readonly IPersistentState<CounterState> _state;

    public CounterGrain(
        [PersistentState("counter", "TableStorage")] IPersistentState<CounterState> state)
        => _state = state;

    public async Task<int> IncrementAsync() {
        _state.State.Count++;
        await _state.WriteStateAsync();  // persist to Azure Table Storage
        return _state.State.Count;
    }

    public Task<int> GetCountAsync() => Task.FromResult(_state.State.Count);

    public async Task ResetAsync() {
        _state.State.Count = 0;
        await _state.WriteStateAsync();
    }
}

