        var questionEmbedding = await embedder.GenerateEmbeddingVectorAsync(question, ct);

        // 2. Retrieve relevant context
        var searchResults = await articles.SearchAsync(
            questionEmbedding,
            new VectorSearchOptions<Article> { Top = 3 });

        var context = string.Join("\n\n", await searchResults.Results
            .Select(r => r.Record.Content).ToListAsync(ct));

        // 3. Generate grounded answer
        var response = await chat.CompleteAsync([
            new ChatMessage(ChatRole.System,
                $"Answer questions based ONLY on the following context:\n{context}"),
            new ChatMessage(ChatRole.User, question)
        ], cancellationToken: ct);

        return response.Message.Text ?? "";
    }
}

