    // critical section
}
// Problem: in thread dumps, just shows as 'System.Object'

// After:
private readonly Lock _lock = new();
// Same syntax:
lock (_lock) {  // compiler calls _lock.EnterScope() automatically
    // critical section
}

// Or explicit scope (using-based):
using (_lock.EnterScope()) {
    // critical section
    // automatically released when scope exits
}

// Debugger: shows 'System.Threading.Lock' — unambiguous in thread dumps
// Also works with Lock.TryEnter(timeout) for non-blocking attempts
bool acquired = _lock.TryEnter(TimeSpan.FromMilliseconds(100));
if (acquired) {
    try { /* critical section */ }
    finally { _lock.Exit(); }
}
