// === Writing a simple incremental source generator ===
[Generator]
public class ToStringGenerator : IIncrementalGenerator {
    public void Initialize(IncrementalGeneratorInitializationContext context) {
        var classes = context.SyntaxProvider.ForAttributeWithMetadataName(
            "GenerateToStringAttribute",
            (node, _) => node is ClassDeclarationSyntax,
            (ctx, _) => (ClassDeclarationSyntax)ctx.TargetNode);

        context.RegisterSourceOutput(classes, (ctx, classDecl) => {
            var source = $$"""
                partial class {{classDecl.Identifier.Text}} {
                    public override string ToString() =>
                        $"{{{classDecl.Identifier.Text}}}: [auto-generated]";
                }
                """;
            ctx.AddSource($"{classDecl.Identifier.Text}.g.cs", source);
        });
    }
}

// === Roslyn analyzer (custom rule) ===
[DiagnosticAnalyzer(LanguageNames.CSharp)]
public class NoDateTimeNowAnalyzer : DiagnosticAnalyzer {
    private static readonly DiagnosticDescriptor Rule = new(
        "NO001", "No DateTime.Now", "Use DateTime.UtcNow or inject IDateTimeProvider",
        "Design", DiagnosticSeverity.Error, isEnabledByDefault: true);

    public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics => [Rule];

    public override void Initialize(AnalysisContext context) {
        context.RegisterSyntaxNodeAction(AnalyzeNode, SyntaxKind.SimpleMemberAccessExpression);
    }

    private void AnalyzeNode(SyntaxNodeAnalysisContext context) {
        var node = (MemberAccessExpressionSyntax)context.Node;
        if (node.Expression.ToString() == "DateTime" && node.Name.Identifier.Text == "Now")
            context.ReportDiagnostic(Diagnostic.Create(Rule, node.GetLocation()));
    }
}
