// === Span<T> — zero-copy slice ===

byte[] buffer = new byte[1024];
Span<byte> span = buffer;                  // no allocation — wraps buffer
Span<byte> header = span.Slice(0, 4);      // no allocation — slice of buffer
Span<byte> payload = span.Slice(4, 100);   // another zero-copy slice

