Span<int> stackInts = stackalloc int[32];  // 32 ints on the STACK, not heap
stackInts[0] = 42;
// Great for small fixed-size scratch buffers

// String without allocation:
ReadOnlySpan<char> text = "Hello, World!".AsSpan();
ReadOnlySpan<char> word = text.Slice(7, 5);  // points into original string
Console.WriteLine(word.ToString());  // "World" — ToString() does allocate
bool starts = text.StartsWith("Hello");  // no allocation

// MemoryExtensions for common string ops (no allocation):
int idx = text.IndexOf(',');  // returns index, no allocation
bool contains = text.Contains("World", StringComparison.Ordinal);

// Span in parsing (HTTP header parsing example):
void ParseHeader(ReadOnlySpan<byte> line) {
    int colonIdx = line.IndexOf((byte)':');
    var name = line.Slice(0, colonIdx);     // zero-copy name
    var value = line.Slice(colonIdx + 2);   // zero-copy value
    // Process name and value as spans — no string allocations
}

// === Memory<T> — async-safe, can store in fields ===

public class NetworkStream {
    private readonly Memory<byte> _buffer;

    public NetworkStream(byte[] backing) {
        _buffer = backing.AsMemory();  // wraps array as Memory<byte>
    }

    public async Task ReadAsync(Memory<byte> output, CancellationToken ct) {
        // Memory<T> can cross await boundaries — Span<T> cannot
        int bytesRead = await _stream.ReadAsync(output, ct);
        // Use output.Span only when sync:
        output.Span.Slice(0, bytesRead).Fill(0);  // zero out read bytes
    }
}

// ArrayPool for reusable buffers (avoids repeated allocations):
byte[] rented = ArrayPool<byte>.Shared.Rent(4096);
try {
    Span<byte> work = rented.AsSpan(0, 4096);
    // ... work with span
} finally {
    ArrayPool<byte>.Shared.Return(rented);  // return to pool
}

// MemoryMarshal for low-level reinterpret casts:
Span<byte> bytes = new byte[] { 0x01, 0x00, 0x00, 0x00 };
int value = MemoryMarshal.Read<int>(bytes);  // reads int from bytes, no copy
